/* verilator lint_off UNUSED */
/* verilator lint_off DECLFILENAME */
// Top-level Verilator testbench wrapper for `hardware/sim/`: instantiates the real dark-RTL vaults
// (`pipelined_risc_core_5stage`, `pipelined_gl_butterfly_4stage`, `gf2_64_wiedemann_tower_mul`,
// `obend_ospc_tile0`) alongside `obend_retimed_mac2`. Hand-written wrapper; every included `.sv`
// module is regenerated byte-for-byte from Lean by `obend-emit-sv` (checked by `verify_sim.sh`).

`include "obend_pipelined_risc64.sv"
`include "obend_goldilocks_bfly4.sv"
`include "obend_gf2_64_karatsuba.sv"
`include "obend_ospc_tile0.sv"
`include "obend_retimed_mac2.sv"

module tb_top (
  input  logic        clk,
  input  logic        rst,

  // 1. 5-stage hazard-forwarding & interlocked 64-bit RISC core (`pipelined_risc_core_5stage`)
  input  logic [63:0] risc_imem_rdata,
  input  logic [63:0] risc_dmem_rdata,
  input  logic [63:0] risc_rf_rdata1,
  input  logic [63:0] risc_rf_rdata2,
  output logic [63:0] risc_imem_addr,
  output logic [63:0] risc_rf_raddr1,
  output logic [63:0] risc_rf_raddr2,
  output logic [63:0] risc_ex_fwd1,
  output logic [63:0] risc_ex_fwd2,
  output logic [63:0] risc_ex_alu_out,
  output logic [63:0] risc_stall_out,
  output logic [63:0] risc_flush_out,
  output logic [63:0] risc_dmem_addr,
  output logic [63:0] risc_dmem_wdata,
  output logic [63:0] risc_dmem_we,
  output logic [63:0] risc_wb_valid,
  output logic [63:0] risc_wb_en,
  output logic [63:0] risc_wb_rd,
  output logic [63:0] risc_wb_data,

  // 2. 4-stage pipelined Goldilocks NTT butterfly (`pipelined_gl_butterfly_4stage`)
  input  logic [63:0] bfly_u_in,
  input  logic [63:0] bfly_v_in,
  input  logic [63:0] bfly_w_in,
  input  logic [0:0]  bfly_in_valid,
  output logic [63:0] bfly_out_even,
  output logic [63:0] bfly_out_odd,
  output logic [0:0]  bfly_out_valid,

  // 3. Carry-free SWAR-Karatsuba + 2-stage pipelined GF(2^64) multiplier (`gf2_64_wiedemann_tower_mul`)
  input  logic [63:0] gf64_a_in,
  input  logic [63:0] gf64_b_in,
  input  logic [0:0]  gf64_in_valid,
  output logic [63:0] gf64_mul_out,
  output logic [63:0] gf64_pipe_out,
  output logic [0:0]  gf64_pipe_valid,

  // 4. OSPC Tile 0 (`FaceIdeal4` 81-bit ternary 4-cube + `ExprCAM` datapath, `obend_ospc_tile0`)
  input  logic [1:0]  ospc_op_sel,
  input  logic [63:0] ospc_in_lo64,
  input  logic [16:0] ospc_in_hi17,
  input  logic [0:0]  ospc_cam_we,
  input  logic [7:0]  ospc_cam_addr,
  input  logic [63:0] ospc_cam_wdata,
  input  logic [63:0] ospc_cam_qtag,
  input  logic [63:0] ospc_cam_q_in,
  output logic [63:0] ospc_out_face_lo64,
  output logic [16:0] ospc_out_face_hi17,
  output logic [0:0]  ospc_out_entails,
  output logic [0:0]  ospc_out_cam_hit,
  output logic [63:0] ospc_out_cam_word,
  output logic [7:0]  ospc_cam_bank_raddr,
  output logic [0:0]  ospc_cam_bank_we,
  output logic [7:0]  ospc_cam_bank_waddr,
  output logic [63:0] ospc_cam_bank_wdata,

  // 5. 2-stage retimed 64-bit MAC (`obend_retimed_mac2`)
  input  logic [63:0] mac_in_a,
  input  logic [63:0] mac_in_b,
  input  logic [63:0] mac_in_c,
  output logic [63:0] mac_out_y
);

  pipelined_risc_core_5stage u_risc64 (
    .clk(clk), .rst(rst),
    .imem_rdata(risc_imem_rdata),
    .dmem_rdata(risc_dmem_rdata),
    .rf_rdata1(risc_rf_rdata1),
    .rf_rdata2(risc_rf_rdata2),
    .imem_addr(risc_imem_addr),
    .rf_raddr1(risc_rf_raddr1),
    .rf_raddr2(risc_rf_raddr2),
    .ex_fwd1(risc_ex_fwd1),
    .ex_fwd2(risc_ex_fwd2),
    .ex_alu_out(risc_ex_alu_out),
    .stall_out(risc_stall_out),
    .flush_out(risc_flush_out),
    .dmem_addr(risc_dmem_addr),
    .dmem_wdata(risc_dmem_wdata),
    .dmem_we(risc_dmem_we),
    .wb_valid(risc_wb_valid),
    .wb_en(risc_wb_en),
    .wb_rd(risc_wb_rd),
    .wb_data(risc_wb_data)
  );

  pipelined_gl_butterfly_4stage u_bfly4 (
    .clk(clk), .rst(rst),
    .u_in(bfly_u_in),
    .v_in(bfly_v_in),
    .w_in(bfly_w_in),
    .in_valid(bfly_in_valid),
    .out_even(bfly_out_even),
    .out_odd(bfly_out_odd),
    .out_valid(bfly_out_valid)
  );

  gf2_64_wiedemann_tower_mul u_gf64 (
    .clk(clk), .rst(rst),
    .a_in(gf64_a_in),
    .b_in(gf64_b_in),
    .in_valid(gf64_in_valid),
    .tower64_mul_out(gf64_mul_out),
    .tower64_pipe_out(gf64_pipe_out),
    .tower64_pipe_valid(gf64_pipe_valid)
  );

  obend_ospc_tile0 u_ospc0 (
    .clk(clk), .rst(rst),
    .op_sel(ospc_op_sel),
    .in_lo64(ospc_in_lo64),
    .in_hi17(ospc_in_hi17),
    .cam_we(ospc_cam_we),
    .cam_addr(ospc_cam_addr),
    .cam_wdata(ospc_cam_wdata),
    .cam_qtag(ospc_cam_qtag),
    .cam_q_in(ospc_cam_q_in),
    .out_face_lo64(ospc_out_face_lo64),
    .out_face_hi17(ospc_out_face_hi17),
    .out_entails(ospc_out_entails),
    .out_cam_hit(ospc_out_cam_hit),
    .out_cam_word(ospc_out_cam_word),
    .cam_bank_raddr(ospc_cam_bank_raddr),
    .cam_bank_we(ospc_cam_bank_we),
    .cam_bank_waddr(ospc_cam_bank_waddr),
    .cam_bank_wdata(ospc_cam_bank_wdata)
  );

  obend_retimed_mac2 u_mac2 (
    .clk(clk), .rst(rst),
    .a(mac_in_a), .b(mac_in_b), .c(mac_in_c),
    .mac_out(mac_out_y)
  );

endmodule
